function money(int|string $minor): string { $value=(int)$minor;return ($value<0?'-':'').number_format(intdiv(abs($value),100),0,',','.').','.str_pad((string)(abs($value)%100),2,'0',STR_PAD_LEFT); }
function reportField(string $key,string $label,string $type='text',string $value=''): void {echo '<label>'.esc($label).'<input name="'.esc($key).'" type="'.esc($type).'" value="'.esc($value).'" required></label>';}
function reportToken(string $action): void {echo '<input type="hidden" name="csrf" value="'.esc($_SESSION['csrf']).'"><input type="hidden" name="action" value="'.esc($action).'"><label class="confirmation"><input type="checkbox" name="confirmed" value="1" required> Confirmo que estos datos están revisados</label>';}
